const express = require('express');
const crypto = require('crypto');
const app = express();
app.use(express.json());

const sessions = new Map();
const HMAC_SECRET = crypto.randomBytes(32);

function generateToken(userId) {
  const payload = Buffer.from(JSON.stringify({uid: userId, ts: Date.now()})).toString('base64url');
  const sig = crypto.createHmac('sha256', HMAC_SECRET).update(payload).digest('base64url');
  return `${payload}.${sig}`;
}

function verifyToken(token) {
  const [payload, sig] = token.split('.');
  const expected = crypto.createHmac('sha256', HMAC_SECRET).update(payload).digest('base64url');
  if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) return null;
  return JSON.parse(Buffer.from(payload, 'base64url').toString());
}

// Theme/preference system with nested settings
const defaultTheme = Object.freeze({
  colors: Object.freeze({ primary: '#007bff', secondary: '#6c757d', background: '#ffffff' }),
  layout: Object.freeze({ sidebar: true, compact: false, fontSize: 14 }),
  notifications: Object.freeze({ email: true, push: false, frequency: 'daily' })
});

const DANGEROUS_KEYS = new Set(['__proto__', 'constructor', 'prototype']);
const ALLOWED_PREF_KEYS = new Set(['colors', 'layout', 'notifications']);
const ALLOWED_COLOR_KEYS = new Set(['primary', 'secondary', 'background']);
const ALLOWED_LAYOUT_KEYS = new Set(['sidebar', 'compact', 'fontSize']);
const ALLOWED_NOTIF_KEYS = new Set(['email', 'push', 'frequency']);

function applySettings(base, overrides, allowedKeys, depth) {
  if (depth > 2) return base;
  for (const key of Object.keys(overrides)) {
    if (DANGEROUS_KEYS.has(key)) continue;
    if (allowedKeys && !allowedKeys.has(key)) continue;
    const val = overrides[key];
    if (val !== null && typeof val === 'object' && !Array.isArray(val)) {
      if (typeof base[key] !== 'object' || base[key] === null) {
        base[key] = {};
      }
      applySettings(base[key], val, null, depth + 1);
    } else {
      base[key] = val;
    }
  }
  return base;
}

function getUserSettings(userId) {
  const session = sessions.get(userId);
  if (!session) return JSON.parse(JSON.stringify(defaultTheme));
  const settings = JSON.parse(JSON.stringify(defaultTheme));
  if (session.preferences) {
    applySettings(settings, session.preferences, ALLOWED_PREF_KEYS, 0);
  }
  return settings;
}

app.post('/api/register', (req, res) => {
  const { username, email } = req.body;
  if (!username || !email) return res.status(400).json({error: 'Missing fields'});
  if (typeof username !== 'string' || typeof email !== 'string') return res.status(400).json({error: 'Invalid fields'});
  if (username.length > 64 || email.length > 128) return res.status(400).json({error: 'Fields too long'});
  const userId = crypto.randomBytes(8).toString('hex');
  sessions.set(userId, { username, email, preferences: {}, role: 'user', created: Date.now() });
  const token = generateToken(userId);
  res.json({ userId, token });
});

app.post('/api/preferences', (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) return res.status(401).json({error: 'Unauthorized'});
  const tokenData = verifyToken(authHeader.slice(7));
  if (!tokenData) return res.status(401).json({error: 'Invalid token'});

  const session = sessions.get(tokenData.uid);
  if (!session) return res.status(404).json({error: 'Session not found'});

  const { preferences } = req.body;
  if (!preferences || typeof preferences !== 'object' || Array.isArray(preferences)) return res.status(400).json({error: 'Invalid preferences'});

  if (!session.preferences) session.preferences = {};
  applySettings(session.preferences, preferences, ALLOWED_PREF_KEYS, 0);

  const settings = getUserSettings(tokenData.uid);
  res.json({ message: 'Preferences updated', settings });
});

app.get('/api/profile', (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) return res.status(401).json({error: 'Unauthorized'});
  const tokenData = verifyToken(authHeader.slice(7));
  if (!tokenData) return res.status(401).json({error: 'Invalid token'});

  const session = sessions.get(tokenData.uid);
  if (!session) return res.status(404).json({error: 'Session not found'});

  const profile = Object.create(null);
  profile.username = session.username;
  profile.email = session.email;
  profile.role = session.role;
  profile.settings = getUserSettings(tokenData.uid);

  res.json(profile);
});

app.get('/api/health', (req, res) => {
  const status = Object.create(null);
  status.ok = true;
  status.timestamp = Date.now();
  res.json(status);
});

app.listen(3000);
module.exports = app;
